WITH ranking AS (  SELECT k.id AS kunde_id, k.name AS kunde, pr.name AS produkt, SUM(p.menge) AS menge,   ROW_NUMBER() OVER (PARTITION BY k.id ORDER BY SUM(p.menge) DESC) AS rn   FROM bestellpositionen p   JOIN bestellungen b ON p.bestellung_id = b.id   JOIN kunden k ON b.kunde_id = k.id   JOIN produkte pr ON p.produkt_id = pr.id   GROUP BY k.id, k.name, pr.id, pr.name) SELECT kunde, produkt, menge FROM ranking WHERE rn = 1 ORDER BY menge DESC, kunde;
